def convert(s, num_rows):
    if num_rows == 1:                                      # a single row means no zigzag happens at all
        return s
    cycle = 2 * num_rows - 2                               # length of one full down then up cycle
    num_cols = (len(s) // cycle + 1) * (num_rows - 1)      # enough columns to fit every cycle plus the diagonals
    grid = [['' for _ in range(num_cols)] for _ in range(num_rows)]  # allocate the full, mostly empty grid
    row, col = 0, 0
    going_down = True
    for ch in s:
        grid[row][col] = ch                                 # place this character at its real zigzag coordinate
        if row == 0:
            going_down = True
        elif row == num_rows - 1:
            going_down = False
        if going_down:
            row += 1
        else:
            row -= 1
            col += 1
    result = []
    for r in range(num_rows):                               # read the grid back row by row
        for c in range(num_cols):
            if grid[r][c] != '':
                result.append(grid[r][c])
    return ''.join(result)


if __name__ == "__main__":
    s = "PAYPALISHIRING"
    num_rows = 3
    print(convert(s, num_rows))

