import java.util.*;

public class Main {
    String convert(String s, int numRows) {
        if (numRows == 1) return s;                              // a single row means no zigzag happens at all
        int cycle = 2 * numRows - 2;                              // length of one full down then up cycle
        int numCols = (s.length() / cycle + 1) * (numRows - 1);   // enough columns to fit every cycle plus the diagonals
        char[][] grid = new char[numRows][numCols];               // allocate the full, mostly empty grid
        int row = 0, col = 0;
        boolean goingDown = true;
        for (char ch : s.toCharArray()) {
            grid[row][col] = ch;                                    // place this character at its real zigzag coordinate
            if (row == 0) goingDown = true;
            else if (row == numRows - 1) goingDown = false;
            if (goingDown) row++;
            else { row--; col++; }
        }
        StringBuilder result = new StringBuilder();
        for (int r = 0; r < numRows; r++) {                        // read the grid back row by row
            for (int c = 0; c < numCols; c++) {
                if (grid[r][c] != '\0') result.append(grid[r][c]);
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        String s = "PAYPALISHIRING";
        int numRows = 3;
        Main solution = new Main();
        System.out.println(solution.convert(s, numRows));
    }
}

