    String convert(String s, int numRows) {
        if (numRows == 1) return s;
        int n = s.length();
        int cycle = 2 * numRows - 2;                              // length of one full down then up cycle
        StringBuilder result = new StringBuilder();
        for (int row = 0; row < numRows; row++) {
            for (int start = row; start < n; start += cycle) {     // every "vertical" character belonging to this row
                result.append(s.charAt(start));
                if (row > 0 && row < numRows - 1) {                   // interior rows also get one "diagonal" character
                    int diagonal = start + cycle - 2 * row;
                    if (diagonal < n) result.append(s.charAt(diagonal));
                }
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        String s = "PAYPALISHIRING";
        int numRows = 3;
        Main solution = new Main();
        System.out.println(solution.convert(s, numRows));
    }
}

